    assert Monad.BitstreamsWithRestIn(h, e') in Rand.eventSpace;
    Rand.ProbIsProbabilityMeasure();
    Measures.BinaryIntersectionIsMeasurable(Rand.eventSpace, Monad.BitstreamsWithValueIn(h, A), Monad.BitstreamsWithRestIn(h, e'));
    reveal DecomposeE;
  }

  lemma ProbabilityOfESimplifyFractions<T(!new)>(xs: seq<T>, ys: seq<T>, p: seq<T>, i: nat, j: nat, h: Monad.Hurd<int>, A: iset<int>, e: iset<Rand.Bitstream>, e': iset<Rand.Bitstream>)
    requires |xs| - i > 1
    ensures (1.0 / ((|xs|-i) as real)) * (1.0 /  NatArith.FactorialTraditional((|xs|-i)-1) as real) == (1.0 * 1.0) / (((|xs|-i) as real) * (NatArith.FactorialTraditional(|xs|-(i+1)) as real))
  {
    var denom := NatArith.FactorialTraditional(|xs|-(i+1)) as real;
    RealArith.SimplifyFractionsMultiplication(1.0, (|xs|-i) as real, 1.0, denom);
  }

  lemma ProbabilityOfEAsRealOfMult<T(!new)>(xs: seq<T>, ys: seq<T>, p: seq<T>, i: nat, j: nat, h: Monad.Hurd<int>, A: iset<int>, e: iset<Rand.Bitstream>, e': iset<Rand.Bitstream>)
    requires |xs| - i > 1
    ensures (((|xs|-i) * NatArith.FactorialTraditional((|xs|-i)-1)) as real) != 0.0
    ensures 1.0 / (((|xs|-i) as real) * NatArith.FactorialTraditional(|xs|-(i+1)) as real) == 1.0 / (((|xs|-i) * NatArith.FactorialTraditional((|xs|-i)-1)) as real)
  {
    RealArith.AsRealOfMultiplication(|xs|-i, NatArith.FactorialTraditional((|xs|-i)-1));
  }

  lemma ProbabilityOfE<T(!new)>(xs: seq<T>, ys: seq<T>, p: seq<T>, i: nat, j: nat, h: Monad.Hurd<int>, A: iset<int>, e: iset<Rand.Bitstream>, e': iset<Rand.Bitstream>)
    requires i <= |xs|
    requires i <= |p|
    requires forall a, b | i <= a < b < |xs| :: xs[a] != xs[b]
    requires |xs| == |p|
    requires multiset(p[i..]) == multiset(xs[i..])
    requires i <= j < |xs| && xs[j] == p[i]
    requires ys == Model.Swap(xs, i, j)
    requires |xs|-i > 1
    requires e' in Rand.eventSpace
    requires |xs| == |ys|
    requires DecomposeE: e == Monad.BitstreamsWithValueIn(h, A) * Monad.BitstreamsWithRestIn(h, e')
    requires HIsIndependent: Independence.IsIndepFunction(h)
    requires hIsMeasurePreserving: Measures.IsMeasurePreserving(Rand.eventSpace, Rand.prob, Rand.eventSpace, Rand.prob, s => h(s).rest)
    requires InductionHypothesis: Rand.prob(e') == 1.0 / (NatArith.FactorialTraditional(|xs|-(i+1)) as real)
    requires BitStreamsInA: Monad.BitstreamsWithValueIn(h, A) == (iset s | Uniform.Model.IntervalSample(i, |xs|)(s).Equals(j))
    ensures
      Rand.prob(e) == 1.0 / (NatArith.FactorialTraditional(|xs|-i) as real)
  {
    var e'' := iset s | Uniform.Model.IntervalSample(i, |xs|)(s).Equals(j);
    assert BitStreamsInALifted: Rand.prob(Monad.BitstreamsWithValueIn(h, A)) * Rand.prob(e') == Rand.prob(e'') * Rand.prob(e') by {
      assert Rand.prob(Monad.BitstreamsWithValueIn(h, A)) == Rand.prob(e'') by {
        reveal BitStreamsInA;
      }
    }

    assert FullIntervalLifted: Rand.prob(e'') * Rand.prob(e') == (1.0 / ((|xs|-i) as real)) * Rand.prob(e') by {
      assert Rand.prob(e'') == 1.0 / ((|xs|-i) as real) by {
        Uniform.Correctness.UniformFullIntervalCorrectness(i, |xs|, j);
      }
      RealArith.MultiplicationInvariance(Rand.prob(e'), Rand.prob(e''), 1.0 / ((|xs|-i) as real));
    }

    var denom := NatArith.FactorialTraditional(|xs|-(i+1)) as real;
    var denom2 := NatArith.FactorialTraditional((|xs|-i)-1) as real;
    var frac := 1.0 / denom;
    var frac2 := 1.0 / denom2;

    assert InductionHypothesisLifted: (1.0 / ((|xs|-i) as real)) * Rand.prob(e') == (1.0 / ((|xs|-i) as real)) * frac by {
      assert Rand.prob(e') == frac by {
        reveal InductionHypothesis;
      }
      RealArith.MultiplicationInvariance(1.0 / ((|xs|-i) as real), Rand.prob(e'), frac);
    }

    assert FracLifted: (1.0 / ((|xs|-i) as real)) * frac == (1.0 / ((|xs|-i) as real)) * frac2 by {
      assert frac == frac2;
      RealArith.MultiplicationInvariance(1.0 / ((|xs|-i) as real), frac, frac2);
    }

    calc {
      Rand.prob(e);
      { reveal DecomposeE; }
      Rand.prob(Monad.BitstreamsWithValueIn(h, A) * Monad.BitstreamsWithRestIn(h, e'));
      { reveal HIsIndependent; reveal InductionHypothesis; reveal hIsMeasurePreserving; Independence.ResultsIndependent(h, A, e'); }
      Rand.prob(Monad.BitstreamsWithValueIn(h, A)) * Rand.prob(e');
      { reveal BitStreamsInALifted; }
      Rand.prob(e'') * Rand.prob(e');
      { reveal FullIntervalLifted; }
      (1.0 / ((|xs|-i) as real)) * Rand.prob(e');
      { reveal InductionHypothesisLifted; }
      (1.0 / ((|xs|-i) as real)) * frac;
      { reveal FracLifted; }
      (1.0 / ((|xs|-i) as real)) * frac2;
      { ProbabilityOfESimplifyFractions(xs, ys, p, i, j, h, A, e, e'); }
      (1.0 * 1.0) / (((|xs|-i) as real) * denom);
      { assert 1.0 * 1.0 == 1.0; }
      1.0 / (((|xs|-i) as real) * denom);
      { ProbabilityOfEAsRealOfMult(xs, ys, p, i, j, h, A, e, e'); }
      1.0 / (((|xs|-i) * NatArith.FactorialTraditional((|xs|-i)-1)) as real);
      { assert (|xs|-i) * NatArith.FactorialTraditional((|xs|-i)-1) == NatArith.FactorialTraditional(|xs|-i) by { reveal NatArith.FactorialTraditional(); } }
      1.0 / (NatArith.FactorialTraditional(|xs|-i) as real);
    }
  }

  lemma MultisetOfSequence<T>(xs: seq<T>, i: nat, j: nat)
    requires i <= j < |xs|
    ensures multiset(xs[i..]) - multiset(xs[i..j]) == multiset(xs[j..])
  {
    calc {
      multiset(xs[i..]) - multiset(xs[i..j]);
      { assert xs[i..] == xs[i..j] + xs[j..]; }
      multiset(xs[i..j] + xs[j..]) - multiset(xs[i..j]);
      { assert  multiset(xs[i..j] + xs[j..]) == multiset(xs[i..j]) + multiset(xs[j..]); }
      multiset(xs[i..j]) + multiset(xs[j..]) - multiset(xs[i..j]);
      multiset(xs[j..]);
    }
  }

  lemma SliceOfSequences<T>(xs: seq<T>, i: nat)
    requires 0 <= i < |xs|
    ensures xs[i..] == [xs[i]] + xs[i+1..]
  {}

  lemma SliceOfSequencesGeneral<T>(xs: seq<T>, i: nat, j: nat)
    requires 0 <= i < j < |xs|
    ensures xs[i..j] == [xs[i]] + xs[i+1..j]
  {}

  lemma SliceOfSequencesVariation<T>(xs: seq<T>, i: nat, j: nat)
    requires 0 <= i <= j < |xs|
    ensures xs[i..] == xs[i..j] + xs[j..]
  {}

